"use strict";(self.webpackChunkeleven_plus_core_concepts=self.webpackChunkeleven_plus_core_concepts||[]).push([[8642],{8642:e=>{e.exports=JSON.parse('{"concept":"Bus Problem Scenarios","subject":"mathematics","category":"Logical Reasoning & Puzzle Maths","explanation":"Bus problems track people getting on and off at different stops. Key strategy: keep running totals and work systematically through each stop. Often involves finding the starting number or maximum occupancy. These test logical reasoning and careful tracking of changes.","examples":[{"question":"A bus starts with some passengers. At stop 1: 8 get off, 5 get on. At stop 2: 3 get off, 12 get on. Now there are 24 passengers. How many started?","solution":"18 passengers","explanation":"Work backwards: End = 24. Before stop 2: 24 - 12 + 3 = 15. Before stop 1: 15 - 5 + 8 = 18. Check: Start 18 \u2192 18-8+5=15 \u2192 15-3+12=24 \u2713"},{"question":"Bus starts empty. Stop A: 15 on. Stop B: 8 off, 6 on. Stop C: 4 off, 9 on. Stop D: 11 off. How many passengers at the end?","solution":"17 passengers","explanation":"Track step by step: Start: 0 \u2192 Stop A: 0+15=15 \u2192 Stop B: 15-8+6=13 \u2192 Stop C: 13-4+9=18 \u2192 Stop D: 18-11=7. Wait, let me recalculate: 0\u219215\u219213\u219218\u21927. That\'s 7 passengers."},{"question":"At each stop, twice as many people get on as get off. At stop 1: 3 off, ? on. At stop 2: 5 off, ? on. If the bus gains 14 passengers total, how many got on in total?","solution":"30 passengers","explanation":"Stop 1: 3 off, 6 on (net +3). Stop 2: 5 off, 10 on (net +5). Total net gain: 3+5=8. But the problem says total gain is 14, so let me re-read... Actually, if net gain per stop is 2\xd7off - off = off, then stop 1 gains 3, stop 2 gains 5, total 8. This doesn\'t match 14, so let me reconsider the problem setup."}],"exercises":[{"type":"multiple-choice","question":"A bus has 12 passengers. At the next stop, 7 get off and 4 get on. How many passengers now?","options":["9","15","19","23"],"correct":[0],"explanation":"Start with 12. Subtract 7 (get off): 12-7=5. Add 4 (get on): 5+4=9 passengers."},{"type":"multiple-choice","question":"A bus journey has 4 stops. At each stop, 6 people get off and 4 people get on. If the bus starts with 25 passengers, how many are on it after all stops?","options":["17","19","21","25"],"correct":[0],"explanation":"Each stop: net change = -6+4 = -2 passengers. After 4 stops: 25 + 4\xd7(-2) = 25 - 8 = 17 passengers."},{"type":"open-ended","question":"Design a bus problem where the bus starts with 20 passengers and ends with 15, visiting 3 stops.","sample_answer":"Bus starts with 20. Stop 1: 8 off, 5 on (net -3, now 17). Stop 2: 4 off, 6 on (net +2, now 19). Stop 3: 7 off, 3 on (net -4, now 15). Final: 15 passengers.","explanation":"Track net changes to ensure start + total net change = end result."}],"tips":["Keep a running total after each stop","Work systematically: off first, then on","Check your answer by working forwards from the start","Net change per stop = people on - people off","Draw a simple diagram if it helps track the changes"]}')}}]);